function get_nist_wavelengths(){
    $items = array();
    $html = get_nist_wavelength_tables_html();
    $rows = explode('</tr>', $html);
    $intensity_to_width = 50;
    foreach ($rows as $row){
        $row = str_replace('&nbsp;', '', $row);
        $row = explode('</td>', $row);
        $row[] = '';
        $row[] = '';
        $row[] = '';
        foreach ($row as &$col){
            $col = trim(strip_tags($col));
        }
        $item = array();
        $row[0] = explode(' ', $row[0]);
        $item['intensity'] = $row[0][0];
        $item['lambda_A'] = $row[1];
        $item['chemical'] = $row[2];
        $item['reference'] = $row[2];        
        //------------------
        // compatibility layer
        $item['caption'] = $item['chemical'];
        $fi = floatval($item['intensity']);
        $fi = $fi ? $fi : 1;
        $width_A = $fi/$intensity_to_width;
        $item["width_mA"] = max(10, $width_A);
        $item["must_include"] = false;
        $items[] = $item;
    }
    return $items;
}

